static inline void i2c_ll_soft_reset(i2c_hw_t *hw)
{
	hw->i2c0_hw->global_ctrl.soft_reset = 1;
	hw->i2c1_hw->global_ctrl.soft_reset = 1;
}

static inline void i2c_ll_soft_reset_instance(i2c_hw_t *hw, i2c_id_t id)
{
	if (id == I2C_ID_0) {
		hw->i2c0_hw->global_ctrl.soft_reset = 1;
	} else if (id == I2C_ID_1) {
		hw->i2c1_hw->global_ctrl.soft_reset = 1;
